use vstd::prelude::*;

verus! {
    // For a non‐empty outer vector `s` of non‐empty character vectors,
    // extract the last character of each inner vector in order.
    fn extract_rear_chars(s: &Vec<Vec<char>>) -> (result: Vec<char>)
        requires
            // Every inner sequence is non‐empty
            forall |i: nat| i < (s.len() as nat) ==> s[i as usize].len() > 0,
        ensures
            // The result has the same length as `s`, and for each i,
            // result[i] == last character of s[i].
            result.len() == s.len() &&
            forall |i: nat| i < (s.len() as nat) ==>
                result[i as usize] == s[i as usize][s[i as usize].len() - 1],
    {
        let mut result: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // Build `result` by pushing the last character of s[i] for i=0..s.len()
        while i < s.len()
            invariant
                // We have processed exactly `i` entries so far
                i <= s.len(),
                result.len() == i,
                // And for each processed index j < i, result[j] is the last of s[j]
                forall |j: nat| j < (i as nat) ==>
                    result[j as usize] == s[j as usize][s[j as usize].len() - 1],
            decreases s.len() - i,
        {
            let inner = &s[i];
            // From the precondition, inner.len() > 0
            assert(inner.len() > 0);
            let last_char = inner[inner.len() - 1];
            result.push(last_char);
            i += 1;
        }

        result
    }
}

